-- Passage rg3-authors-purpose-p03
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('269f532d-ec03-503a-9a39-be42ef1e29ec', 'rg3-authors-purpose-p03', (select id from public.skills where slug = 'read-g3-authors-purpose'), null,
        '3-5', $q$The Desert After Dark$q$, $q$During the day, the desert can look empty. The sun is hot, and the sand glows pale yellow. Most animals hide in burrows or under rocks to stay cool.

When the sun goes down, the desert changes. The air turns cool. The sky fills with bright stars. Soon, the desert begins to wake up.

A kangaroo rat hops out of its hole. It has big back legs and a long tail with a puff of fur at the end. It searches the sand for seeds. Nearby, a small owl sits on top of a tall cactus. Its yellow eyes watch the ground below.

Some desert flowers open only at night. Their petals are white, so they are easy to see in the moonlight. Moths flutter around them to drink their nectar.

By morning, the desert grows quiet again. The animals return to their homes. The night flowers close up tight. The desert looks empty once more, but now you know its secret.$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
where public.passages.status = 'draft';
