-- Passage rg3-authors-purpose-p06
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('8451fdcf-54de-5c15-979f-833b6e6c939a', 'rg3-authors-purpose-p06', (select id from public.skills where slug = 'read-g3-authors-purpose'), null,
        '3-5', $q$How to Dribble a Soccer Ball$q$, $q$In soccer, dribbling means moving the ball down the field with your feet. Good dribbling keeps the ball close so other players cannot take it. Here is how to learn this skill.

First, use the inside of your foot. This part of your foot is wide and flat, so it gives you more control. Tap the ball gently. If you kick it too hard, it will roll away from you.

Next, keep the ball close. Try to touch it every step or two. Stay on the balls of your feet so you can turn quickly.

Then, look up. Many new players stare down at the ball the whole time. But you need to see your teammates and the open space. Take quick peeks at the ball, then lift your eyes again.

Finally, practice often. Set up a few cones or water bottles in a line. Dribble in and out of them slowly. As you get better, go a little faster. With practice, dribbling will start to feel easy.$q$, 'draft')
